@torch.jit.script
def _reset_floor_gru_layer(inputs: torch.Tensor, hidden: torch.Tensor,
                          weight_ih: torch.Tensor, weight_hh: torch.Tensor,
                          bias_ih: torch.Tensor, bias_hh: torch.Tensor):
    input_gates = torch.nn.functional.linear(inputs, weight_ih, bias_ih)
    outputs = torch.jit.annotate(list[torch.Tensor], [])
    for step in range(inputs.size(1)):
        input_reset, input_update, input_new = input_gates[:, step].chunk(3, dim=-1)
        hidden_reset, hidden_update, hidden_new = torch.nn.functional.linear(
            hidden, weight_hh, bias_hh
        ).chunk(3, dim=-1)
        reset = 0.1 + 0.9 * torch.sigmoid(input_reset + hidden_reset)
        update = torch.sigmoid(input_update + hidden_update)
        candidate = torch.tanh(input_new + reset * hidden_new)
        hidden = candidate + update * (hidden - candidate)
        outputs.append(hidden)
    return torch.stack(outputs, dim=1), hidden


